-- lovable-cron-fallback-reviewed: Maintain existing pending-only five-minute retry schedule; no new recurring jobs, immediate wake belongs only to enqueue and productive batches.
CREATE OR REPLACE FUNCTION public.email_arm_dispatch() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j bigint; pending boolean; BEGIN PERFORM pg_advisory_xact_lock(hashtext('email-dispatch-scheduler')); SELECT EXISTS(SELECT 1 FROM public.email_recipients r JOIN public.email_campaigns c ON c.id=r.campaign_id WHERE r.status IN ('queued','sending') AND c.status IN ('queued','sending')) INTO pending; SELECT jobid INTO j FROM cron.job WHERE jobname='email-pending-dispatch'; IF pending AND j IS NULL THEN PERFORM cron.schedule('email-pending-dispatch','*/5 * * * *','SELECT public.email_wake_dispatch()'); ELSIF NOT pending AND j IS NOT NULL THEN PERFORM cron.unschedule(j); END IF; END $$; REVOKE ALL ON FUNCTION public.email_arm_dispatch() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_arm_dispatch() TO service_role;
CREATE OR REPLACE FUNCTION public.email_activate_bundle(_account uuid,_plan text,_contacts integer,_limit integer,_price numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.email_bundles; charge numeric; BEGIN INSERT INTO public.email_bundles(account_id) VALUES(_account) ON CONFLICT DO NOTHING; SELECT * INTO b FROM public.email_bundles WHERE account_id=_account FOR UPDATE; IF b.plan <> 'free' AND b.status='active' AND b.period_end>now() THEN RAISE EXCEPTION 'Your paid bundle is already active. Cancel renewal before changing it.'; END IF; IF _plan NOT IN ('standard','pro') OR _price<=0 OR _contacts<500 THEN RAISE EXCEPTION 'Invalid bundle'; END IF; charge:=round(_price*CASE WHEN b.paid_months<3 THEN 0.7 ELSE 1 END,2); PERFORM public.debit_account(_account,charge,NULL,'Email '||_plan||' monthly bundle'); UPDATE public.email_bundles SET plan=_plan,contact_limit=_contacts,email_limit=CASE WHEN _plan='pro' THEN NULL ELSE _limit END,monthly_price=_price,period_start=now(),period_end=now()+interval '1 month',used=0,paid_months=b.paid_months+1,status='active',renew=true,updated_at=now() WHERE account_id=_account; END $$; REVOKE ALL ON FUNCTION public.email_activate_bundle(uuid,text,integer,integer,numeric) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_activate_bundle(uuid,text,integer,integer,numeric) TO service_role;